42:final class JsonlSessionCreateOptions {
43:  /// Creates [JsonlSessionCreateOptions].
44:  const JsonlSessionCreateOptions({
45:    required this.cwd,
46:    this.id,
47:    this.parentSessionPath,
48:    this.metadata,
49:  });
50:
51:  /// Working directory the session belongs to (determines its directory).
52:  final String cwd;
53:
54:  /// Explicit session id; a fresh uuidv7 is generated when omitted.
55:  final String? id;
