64:/// The repository contract for sessions.
65:///
66:/// Ported from pi's `SessionRepo` (specialized to JSONL metadata/options).
67:abstract interface class SessionRepo {
68:  /// Creates a new session.
69:  Future<Session> create(JsonlSessionCreateOptions options);
70:
71:  /// Opens an existing session from its metadata. With [windowed] only
72:  /// the header plus the newest chunk are materialized; with
73:  /// [wholeFileOnly] the full open takes the classic whole-file read even
74:  /// on a ranged filesystem (error-recovery fallbacks: a retry after a
75:  /// ranged-read failure must not depend on that capability again).
76:  Future<Session> open(
77:    SessionMetadata metadata, {
78:    bool windowed = false,
79:    bool wholeFileOnly = false,
80:  });
81:
82:  /// Lists stored sessions, newest first; [cwd] filters to one directory.
83:  Future<List<SessionMetadata>> list({String? cwd});
84:
85:  /// Deletes a session file.
86:  ///
87:  /// Issue #522: the delete is journaled (who/what/when into the root's
88:  /// `session_ops.journal`), soft (the file moves into `<root>/.trash/`),
89:  /// and refused with [SessionErrorCode.liveSession] while a fresh
90:  /// presence row exists for the session — unless the deleting process
91:  /// owns that row. [actor] names the calling flow for the journal.
92:  Future<void> delete(SessionMetadata metadata, {String actor = 'unknown'});
93:
94:  /// Forks [source] into a new session containing a prefix of its tree.
95:  ///
96:  /// When [entryId] is given, the fork contains the branch ending at that
97:  /// entry ([ForkPosition.at]) or everything before it, which requires the
98:  /// entry to be a user message ([ForkPosition.before], the default).
99:  Future<Session> fork(
100:    SessionMetadata source, {
101:    required String cwd,
102:    String? entryId,
103:    ForkPosition position,
104:    String? id,
105:    String? parentSessionPath,
106:    Map<String, dynamic>? metadata,
107:  });
108:}
