376:  @override
377:  Future<void> delete(
378:    SessionMetadata metadata, {
379:    String actor = 'unknown',
380:  }) async {
381:    // Issue #522 live guard: a fresh presence row means a running process
382:    // owns this session. `list()` already expired stale heartbeats, so a
383:    // dead owner never blocks. The owner itself may delete its own file
384:    // (the emptiness-gated cleanup flows) — that is the pid match.
385:    final row = (await presenceStore?.list())?[metadata.id];
386:    final ownRow = row != null && processId != null && row.pid == processId;
387:    if (row != null && !ownRow) {
388:      throw SessionException(
389:        'Session ${metadata.id} is live (pid ${row.pid ?? 'unknown'}, '
390:        'heartbeat ${row.touchedAt}) — delete refused. Stop the owning '
391:        'process first; the refusal is itself the data-loss guard.',
392:        code: SessionErrorCode.liveSession,
393:      );
394:    }
395:    await _softDelete(
396:      metadata.path,
397:      op: 'delete',
398:      sessionId: metadata.id,
399:      actor: actor,
