403:  /// Trashes every `.jsonl` session whose file contains **only the header
404:  /// record** and no further entries.
405:  ///
406:  /// Used after the migrate-from-eager-creation change to clean up the
407:  /// legacy empty files that the old `SubagentManager.register` /
408:  /// `AgentService.initialize` paths left on disk. Returns the number of
409:  /// files actually trashed (best-effort: a failed read leaves the file in
410:  /// place). Issue #522: empty does not mean deletable while live — a
411:  /// just-booted process owns a header-only file, so live rows are skipped,
412:  /// and everything routes through the journaled soft-delete gate.
413:  ///
414:  /// gh-1660: with [olderThan] set, only header-only files whose mtime is
415:  /// older than that age are swept — a brand-new header-only file is
416:  /// exactly what a concurrently booting process owns between `create`
417:  /// and its first append (and what its presence row may not cover yet),
418:  /// so the age guard is what makes boot-time sweeps race-safe. Null
419:  /// keeps the legacy sweep-everything behavior.
420:  Future<int> cleanupEmptySessions({Duration? olderThan}) async {
421:    var removed = 0;
422:    final root = await _getSessionsRoot();
423:    final rootExists = _fsOrThrow(
424:      await _fs.exists(root),
425:      'Failed to check sessions root $root',
426:    );
427:    if (!rootExists) return 0;
428:    final live = (await presenceStore?.list()) ?? const {};
429:    final cutoff = olderThan == null ? null : now().subtract(olderThan);
430:    final files = await _collectJsonlFileInfos(root);
431:    for (final entry in files) {
432:      final path = entry.path;
433:      // Emptiness is decidable from the first two lines: line 1 is the
434:      // header, and any transcript content means a second line. The read
435:      // streams and stops there — scanning every session whole would turn
436:      // the cleanup pass into O(bytes on disk) and defeat windowed
437:      // loading (issue #135) on big session files. (fa writers never emit
438:      // blank lines, so "second line empty" can only mean "no content".)
439:      final lines = _fsOrThrow(
440:        await _fs.readTextLines(path, maxLines: 2),
441:        'Failed to read $path',
442:      );
443:      final nonEmpty = lines.where((line) => line.trim().isNotEmpty).length;
444:      if (nonEmpty > 1) continue;
445:      final id = _sessionIdFromPath(path);
446:      if (id != null && live.containsKey(id)) continue;
447:      if (cutoff != null &&
448:          !DateTime.fromMillisecondsSinceEpoch(
449:            entry.mtimeMs,
450:          ).isBefore(cutoff)) {
451:        continue;
452:      }
453:      await _softDelete(
454:        path,
455:        op: 'cleanup-empty',
456:        sessionId: id,
457:        actor: 'repo:cleanup-empty',
458:      );
459:      removed++;
460:    }
461:    return removed;
462:  }
