464:  /// The `.trash` directory under the sessions root (issue #522): deleted
465:  /// session files land here — `<root>/.trash/<timestamp>_<name>` — and
466:  /// stay recoverable until [purgeTrash] drops them past a TTL.
467:  static const String trashDirName = '.trash';
468:
469:  /// The per-root deletion journal (issue #522): one JSON line per
470:  /// delete/move/purge with the culprit (pid + actor tag), the path, and
471:  /// the outcome. A vanished session file always has a named record.
472:  static const String journalFileName = 'session_ops.journal';
473:
474:  /// Moves [path] into `<root>/.trash/` and journals the operation.
475:  ///
476:  /// Trash-first: the move is atomic, so a crash can only leave the file
477:  /// recoverable in `.trash` (its presence there IS the record) or in
478:  /// place — never gone. Backends without a rename primitive (pure web)
479:  /// fall back to a journaled remove: the intent line lands BEFORE the
480:  /// unlink so even that path names its culprit.
481:  ///
482:  /// Issue #863: a rename that fails as `notSupported` (a decorator env
483:  /// advertising the capability its delegate lacks) falls back to
484:  /// copy+delete so the session is still really deleted, and every
485:  /// success path is verified — a backend that reports success but left
486:  /// the file in place raises instead of passing as a silent no-op.
487:  Future<void> _softDelete(
488:    String path, {
489:    required String op,
490:    String? sessionId,
491:    required String actor,
492:  }) async {
493:    final root = await _getSessionsRoot();
494:    final exists = _fsOrThrow(
495:      await _fs.exists(path),
496:      'Failed to check session $path',
497:    );
498:    if (!exists) {
499:      await _journal(
500:        root,
501:        op: op,
502:        path: path,
503:        sessionId: sessionId,
504:        actor: actor,
505:        result: 'missing',
506:      );
507:      return;
508:    }
509:    final trashPath = await _trashPathFor(root, path);
510:    if (_fs is! RenamableFileSystem) {
511:      await _journal(
512:        root,
513:        op: op,
514:        path: path,
515:        sessionId: sessionId,
516:        actor: actor,
517:        result: 'remove-fallback',
518:      );
519:      _fsOrThrow(
520:        await _fs.remove(path, force: true),
521:        'Failed to delete session $path',
522:      );
523:      await _verifyGone(path);
524:      return;
525:    }
526:    final trashDir = _fsOrThrow(
527:      await _fs.joinPath([root, trashDirName]),
528:      'Failed to resolve trash directory',
529:    );
530:    _fsOrThrow(
531:      await _fs.createDir(trashDir, recursive: true),
532:      'Failed to create trash directory',
533:    );
534:    final renamed = await (_fs as RenamableFileSystem).renamePath(
535:      path,
536:      trashPath,
537:    );
538:    if (renamed.isErr) {
539:      final error = renamed.errorOrNull!;
540:      if (error.code != FileErrorCode.notSupported) {
541:        _fsOrThrow(renamed, 'Failed to move session $path to trash $trashPath');
542:      }
543:      // The decorator/rename gap behind issue #863 ("renamePath not
544:      // supported by Instance of 'LocalExecutionEnv'"): copy+delete so the
545:      // delete happens for real — trash copy first, then the unlink, both
546:      // journaled via the intent line below.
547:      final info = _fsOrThrow(
548:        await _fs.fileInfo(path),
549:        'Failed to stat session $path for the trash copy',
550:      );
551:      if (info.size > maxTrashCopyBytes) {
552:        // The fallback stages the trash copy in RAM (no streaming write
553:        // on the FileSystem interface); refuse oversized sessions instead
554:        // of spiking a low-RAM device (issue #863 review).
555:        throw SessionException(
556:          'Session $path (${info.size} bytes) is too large to stage the '
557:          'trash copy on a rename-less backend (limit $maxTrashCopyBytes '
558:          'bytes); delete it from a host with rename support',
559:          code: SessionErrorCode.storage,
560:        );
561:      }
562:      await _journal(
563:        root,
564:        op: op,
565:        path: path,
566:        sessionId: sessionId,
567:        actor: actor,
568:        result: 'copy-delete',
569:      );
570:      final bytes = _fsOrThrow(
571:        await _fs.readBinaryFile(path),
572:        'Failed to read session $path for the trash copy',
573:      );
574:      _fsOrThrow(
575:        await _fs.writeBinaryFile(trashPath, bytes),
576:        'Failed to write trash copy $trashPath',
577:      );
578:      _fsOrThrow(
579:        await _fs.remove(path, force: true),
580:        'Failed to delete session $path',
581:      );
582:    } else {
583:      await _journal(
584:        root,
585:        op: op,
586:        path: path,
587:        sessionId: sessionId,
588:        actor: actor,
589:        result: 'trash',
590:        trash: trashPath,
591:      );
592:    }
593:    await _verifyGone(path);
594:  }
