624:  /// Appends one auditable line to the root's `session_ops.journal`.
625:  Future<void> _journal(
626:    String root, {
627:    required String op,
628:    required String path,
629:    String? sessionId,
630:    required String actor,
631:    required String result,
632:    String? trash,
633:  }) async {
634:    final line = json_conv.jsonEncode({
635:      'at': now().toIso8601String(),
636:      'op': op,
637:      'path': path,
638:      'session': ?sessionId,
639:      'pid': ?processId,
640:      'actor': actor,
641:      'result': result,
642:      'trash': ?trash,
643:    });
644:    final journalPath = _fsOrThrow(
645:      await _fs.joinPath([root, journalFileName]),
646:      'Failed to resolve journal path',
647:    );
