654:  /// Removes trash entries older than [ttl] (issue #522): trash is
655:  /// recoverable storage with a lifetime, not an unbounded second copy of
656:  /// every deleted session. Returns the number of entries purged; every
657:  /// purge is journaled.
658:  Future<int> purgeTrash({
659:    Duration ttl = const Duration(days: 30),
660:    String actor = 'repo:purge-trash',
661:  }) async {
662:    final root = await _getSessionsRoot();
663:    final trashDir = _fsOrThrow(
664:      await _fs.joinPath([root, trashDirName]),
665:      'Failed to resolve trash directory',
666:    );
667:    if (!_fsOrThrow(await _fs.exists(trashDir), 'Failed to check $trashDir')) {
668:      return 0;
669:    }
670:    final entries = _fsOrThrow(
671:      await _fs.listDir(trashDir),
672:      'Failed to list $trashDir',
673:    );
674:    final cutoffMs = now().subtract(ttl).millisecondsSinceEpoch;
675:    var purged = 0;
676:    for (final entry in entries) {
677:      if (entry.mtimeMs >= cutoffMs) continue;
678:      _fsOrThrow(
679:        await _fs.remove(entry.path, force: true),
680:        'Failed to purge ${entry.path}',
681:      );
682:      await _journal(
683:        root,
684:        op: 'purge',
685:        path: entry.path,
686:        actor: actor,
687:        result: 'removed',
688:      );
689:      purged++;
690:    }
691:    return purged;
692:  }
