694:  /// The session id encoded in a session file basename
695:  /// (`<timestamp>_<sessionId>.jsonl`); null when the name has no id part.
696:  String? _sessionIdFromPath(String path) {
697:    final base = path.split(RegExp(r'[/\\]')).last;
698:    if (!base.endsWith('.jsonl')) return null;
699:    final parts = base.substring(0, base.length - '.jsonl'.length).split('_');
700:    return parts.length < 2 || parts.last.isEmpty ? null : parts.last;
