703:  /// The session sweep's file walk (gh-1660 age guard reads the mtime):
704:  /// every `.jsonl` under [dirPath], carrying each file's [FileInfo].
705:  Future<List<FileInfo>> _collectJsonlFileInfos(String dirPath) async {
706:    final entries = _fsOrThrow(
707:      await _fs.listDir(dirPath),
708:      'Failed to list session directory $dirPath',
709:    );
710:    final files = <FileInfo>[];
711:    for (final entry in entries) {
712:      if (entry.kind == FileKind.directory) {
713:        // The trash (issue #522) is recoverable storage, not a session
714:        // folder — its files must never re-enter list()/cleanup sweeps.
715:        if (entry.name == trashDirName) continue;
716:        files.addAll(await _collectJsonlFileInfos(entry.path));
717:        continue;
718:      }
719:      if (entry.name.endsWith('.jsonl')) files.add(entry);
720:    }
721:    return files;
