767:  /// newest `session_info` record — the same record `(await open(m))
768:  /// .getSessionName()` reports within the probe cap (an empty or
769:  /// whitespace newest name clears it). Read-only: never rewrites torn
770:  /// lines. Issue #369 — the CLI cold start resolves `--session NAME`
771:  /// across every session file, and named-at-creation sessions
772:  /// keep their only session_info at the file START, so chunk-paged
773:  /// parsing made a 400 MB file cost its whole JSON body per scan.
774:  /// Resolution is two bounded byte probes instead: the file's head
775:  /// window first (where creation-time names live), then the tail
776:  /// window, whose record wins whenever present — at most `2 MiB` +
777:  /// the probed lines' bytes, never a full read, on hosts with ranged
778:  /// reads (ranged-read support is required; hosts without it cannot
779:  /// open sessions windowed at all). Throws [SessionException] like
780:  /// [open] when the file is missing/unreadable — callers already
781:  /// guard.
782:  Future<String?> sessionNameQuick(SessionMetadata metadata) async {
783:    // Rotated sessions (gh-1077): probe every segment, newest first —
784:    // the newest session_info record anywhere in the chain decides,
785:    // exactly as in a single file (an empty name CLEARS an older one).
786:    final paths = await listSessionSegmentPaths(_fs, metadata.path);
787:    for (final path in paths.reversed) {
788:      final reader = SessionChunkReader(
789:        fs: _fs,
790:        path: path,
791:        parseExecutor: _parseExecutor,
792:      );
793:      SessionInfoRecord? info;
794:      try {
795:        info = await reader.readNewestSessionInfo();
796:      } on SessionException {
797:        if (path == metadata.path) rethrow;
798:        continue; // an unreadable part must not kill name resolution
799:      }
800:      if (info == null) continue;
801:      final trimmed = info.name?.trim();
802:      return trimmed == null || trimmed.isEmpty ? null : trimmed;
803:    }
804:    return null;
805:  }
806:
807:  /// Raw file scan for custom records whose `customType` is in [types]
808:  /// (issue #437). Custom records are side-leaves of the record tree, so
809:  /// the windowed storage's branch parse never materializes them into
810:  /// [Session.getEntries] — restart-time scans (e.g. recovered steering)
811:  /// must read the file instead of trusting the resident window. The
812:  /// cheap substring gate keeps JSON decodes proportional to the match
813:  /// count, not the file size. Returns [] for a missing/unreadable file:
814:  /// a broken session must still boot.
815:  ///
816:  /// Ranged-read hosts stream the file in bounded blocks (issue #503 boot
817:  /// cost): the previous whole-file [FileSystem.readTextLines] pass
818:  /// materialized a marathon session as one giant string plus a
819:  /// per-line list — ~2.7s of read+decode+split on a 434MB file, paid on
820:  /// every boot. The streamed path keeps memory flat and UTF-8-decodes
821:  /// only lines that pass the byte-level gate (type names are ASCII, so a
822:  /// byte scan is exact); line boundaries are found on raw bytes, which
823:  /// is UTF-8-safe (`0x0A` never appears inside a multi-byte sequence).
824:  ///
825:  /// With [lastSegmentOnly] only the PRIMARY segment (the live file) is
826:  /// scanned instead of the whole `.part-NN` chain — O(tail) cost for
827:  /// boot-path callers whose records are tail-appended during runs
828:  /// (gh-1449's orphan-report seed). The trade-off is explicit: records
829:  /// already rotated into an older segment are invisible to the scan, so
830:  /// such a caller may re-report once after a resume; use it only where
831:  /// that degradation is acceptable and the chain walk must not sit on
832:  /// the boot path (the #503 precedent).
833:  Future<List<CustomRecord>> readCustomRecordsOfType(
834:    SessionMetadata metadata,
835:    Set<String> types, {
836:    bool lastSegmentOnly = false,
837:    // Non-null default so an EXPLICIT `null` is distinguishable from
838:    // omitting the parameter (review: `?? cap` here made the documented
839:    // unbounded opt-out a silent no-op — null coalesced to the default).
840:    int? tailCapBytes = kSessionSegmentHardCapBytes,
841:  }) async {
842:    // Rotated sessions (gh-1077) keep older records in `.part-NN`
843:    // segments: scan the whole chain in order or registry snapshots
844:    // flushed before the last rotation become invisible to subagent
845:    // adoption (#488), memory refresh and ttsr. Dedupe by record id:
846:    // between a failed rotation seed and the next open the archived
847:    // part and the restored primary hold the SAME records — the open
848:    // path dedupes (seenRecordIds), the raw scan must too (round 5).
849:    //
850:    // Tail cap (the goal_builder 2.7GB incident): the windowed storage
851:    // never rotates, so a marathon session's PRIMARY grows unbounded
852:    // (measured 2.7GB against the 80MB rotate / 95MB hard-cap design),
853:    // and a from-offset-0 scan of it sat on the resume boot path for
854:    // 10+ seconds (orphan-report seed) and churned post-boot
855:    // (steering, obligations). Every consumer today is a TAIL consumer
856:    // (`records.last`, or pending-vs-consumed steering where a pair
857:    // entirely beyond the cap cancels itself), so the default bounds
858:    // each FILE to the tail region a properly rotated primary promised
859:    // ([kSessionSegmentHardCapBytes]); rotated `.part-NN` files are
860:    // smaller than that and scan in full. Deep-history callers pass an
861:    // EXPLICIT `tailCapBytes: null` (the parameter defaults to the cap,
862:    // so only an explicit null is unbounded).
863:    final cap = tailCapBytes;
864:    final paths = await listSessionSegmentPaths(_fs, metadata.path);
865:    final scanned = lastSegmentOnly ? paths.sublist(paths.length - 1) : paths;
866:    final records = <CustomRecord>[];
867:    final seen = <String>{};
868:    for (final path in scanned) {
869:      for (final record in await _readCustomRecordsInFile(path, types, cap)) {
870:        if (seen.add(record.id)) records.add(record);
871:      }
872:    }
873:    return records;
874:  }
875:
876:  /// Single-file scan behind [readCustomRecordsOfType]; see its
877:  /// docstring. Returns [] for a missing/unreadable file.
878:  Future<List<CustomRecord>> _readCustomRecordsInFile(
879:    String path,
880:    Set<String> types,
881:    int? tailCapBytes,
882:  ) async {
883:    final fs = _fs;
884:    if (fs case final RangedReadFileSystem ranged) {
885:      return _readCustomRecordsStreamed(fs, ranged, path, types, tailCapBytes);
886:    }
887:    // Non-ranged filesystems (in-memory hosts) carry small sessions;
888:    // the cap degrades to no-op there rather than approximating byte
889:    // offsets over decoded lines.
890:    final read = await fs.readTextLines(path);
891:    if (read.isErr) return const [];
892:    final records = <CustomRecord>[];
893:    for (final line in read.valueOrNull ?? const <String>[]) {
894:      if (!types.any(line.contains)) continue;
895:      _decodeCustomRecord(line, types, records);
896:    }
897:    return records;
898:  }
899:
900:  /// Full-archive search over [metadata]'s session chain (issue #1380
901:  /// A2): the streamed, bounded scan in `session_search.dart` run against
902:  /// this repo's file system — the repo exists so hosts never need the
903:  /// private fs to reach the file.
904:  Future<SessionSearchOutcome> searchArchive(
905:    SessionMetadata metadata,
906:    SessionSearchQuery query,
907:  ) => searchSessionFile(_fs, metadata.path, query);
908:
909:  /// Scan block size for [_readCustomRecordsStreamed]; tests shrink it to
910:  /// exercise the block-seam logic (lines and gates spanning blocks).
911:  @visibleForTesting
912:  static var debugCustomRecordScanBlockBytes = 8 << 20;
913:
914:  /// Blocked scan behind [readCustomRecordsOfType]; see its docstring.
915:  ///
916:  /// Per-block pipeline: `latin1.decode` (byte→char identity memcpy —
917:  /// measured 3x cheaper than validating `utf8.decode`, 322ms vs 941ms
918:  /// on a 434MB marathon file), then gate-hit scanning via native
919:  /// `String.indexOf` — hits are as rare as the records themselves (14
920:  /// on that file), so full lines materialize only around an actual hit
921:  /// instead of substring-copying every line for a per-line `contains`.
922:  /// latin1 is byte-exact for the ASCII gate and line feeds, and
923:  /// `latin1.encode` restores a matching line's original bytes for the
924:  /// real `utf8.decode` + `jsonDecode` — semantics identical to the
925:  /// whole-file path.
926:  Future<List<CustomRecord>> _readCustomRecordsStreamed(
927:    FileSystem fs,
928:    RangedReadFileSystem ranged,
929:    String path,
930:    Set<String> types,
931:    int? tailCapBytes,
932:  ) async {
933:    final blockBytes = debugCustomRecordScanBlockBytes;
934:    final info = await fs.fileInfo(path);
935:    if (info.isErr) return const [];
936:    if (info.valueOrNull!.kind != FileKind.file) return const [];
937:    final size = info.valueOrNull!.size;
938:    final scanner = _CustomRecordBlockScanner(types);
939:    // Start inside the tail region: a line torn at the boundary simply
940:    // fails the field-shaped gate (or jsonDecode) and is skipped — the
941:    // cap trades deep history, never correctness.
942:    var offset = tailCapBytes == null ? 0 : math.max(0, size - tailCapBytes);
943:    while (offset < size) {
944:      final end = (offset + blockBytes).clamp(0, size);
945:      final read = await ranged.readRange(path, offset, end);
946:      if (read.isErr) return const [];
947:      final block = read.valueOrNull!;
948:      if (block.isEmpty) break;
949:      offset = end;
950:      scanner.scanBlock(json_conv.latin1.decode(block));
951:    }
952:    return scanner.finish();
953:  }
954:
955:  /// Decodes one gated line into [records]; malformed JSON (crash-torn
956:  /// tail) and non-matching parsed records are skipped.
957:  static void _decodeCustomRecord(
958:    String line,
959:    Set<String> types,
960:    List<CustomRecord> records,
961:  ) {
962:    final Object? json;
963:    try {
964:      json = json_conv.jsonDecode(line);
965:    } on Object {
966:      return; // torn tail line from a crash — skip.
967:    }
968:    if (json is! Map) return;
969:    final record = SessionRecord.fromJson(json.cast<String, dynamic>());
970:    if (record is CustomRecord && types.contains(record.customType)) {
971:      records.add(record);
972:    }
973:  }
