975:  /// Batch form of [sessionNameQuick]: bounded 16-way fan-out, results
976:  /// keyed by session id; a session that fails to scan contributes no
977:  /// name (the caller's row degrades to the id).
978:  Future<Map<String, String>> sessionNamesQuick(
979:    List<SessionMetadata> sessions,
980:  ) async {
981:    final names = <String, String>{};
982:    var next = 0;
983:    Future<void> worker() async {
984:      while (next < sessions.length) {
985:        final metadata = sessions[next++];
986:        try {
987:          final name = await sessionNameQuick(metadata);
988:          if (name != null) names[metadata.id] = name;
989:        } on Object {
990:          // Broken or foreign session file: skip, never break the caller.
991:        }
992:      }
993:    }
994:
995:    await Future.wait([
996:      for (var i = 0; i < _listConcurrency && i < sessions.length; i++)
997:        worker(),
998:    ]);
999:    return names;
1000:  }
