1002:  Future<List<SessionMetadata>> _collectRootSessions() async {
1003:    final root = await _getSessionsRoot();
1004:    final exists = _fsOrThrow(
1005:      await _fs.exists(root),
1006:      'Failed to check sessions root $root',
1007:    );
1008:    if (!exists) return [];
1009:    return _collectSessionsInDir(root);
1010:  }
1011:
1012:  /// Collects every session file under the root: the directory tree is
1013:  /// walked breadth-first with bounded parallel [listDir] calls, then all
1014:  /// header reads fan out through ONE bounded pool (issue #199 AC3 —
1015:  /// sequential listing makes app boot O(sessions × header latency)).
1016:  Future<List<SessionMetadata>> _collectSessionsInDir(String dirPath) async {
1017:    final files = <FileInfo>[];
1018:    final pending = <String>[dirPath];
1019:    while (pending.isNotEmpty) {
1020:      final level = List.of(pending);
1021:      pending.clear();
1022:      final discovered = await _mapBounded(level, _listDir);
1023:      for (final entries in discovered) {
1024:        for (final entry in entries) {
1025:          if (entry.kind == FileKind.directory) {
1026:            // Trash (issue #522) never surfaces as live sessions.
1027:            if (entry.name == trashDirName) continue;
1028:            pending.add(entry.path);
1029:          } else if (entry.name.endsWith('.jsonl')) {
1030:            files.add(entry);
1031:          }
1032:        }
1033:      }
1034:    }
1035:    final loaded = await _mapBounded<FileInfo, SessionMetadata?>(
1036:      files,
1037:      _tryLoadSessionMetadata,
1038:    );
1039:    return [for (final m in loaded) ?m];
1040:  }
1041:
1042:  /// Runs [task] over [items] with at most [_listConcurrency] in flight;
1043:  /// results keep input order. A failing task fails the whole batch (the
1044:  /// caller's error text names its item).
1045:  Future<List<R>> _mapBounded<T, R>(
1046:    List<T> items,
1047:    Future<R> Function(T) task,
1048:  ) async {
1049:    final results = List<R?>.filled(items.length, null);
1050:    var next = 0;
1051:    Future<void> worker() async {
1052:      while (true) {
1053:        final i = next++;
1054:        if (i >= items.length) return;
1055:        results[i] = await task(items[i]);
1056:      }
1057:    }
1058:
1059:    await Future.wait([
1060:      for (var i = 0; i < _listConcurrency && i < items.length; i++) worker(),
1061:    ]);
1062:    return [for (final r in results) r as R];
1063:  }
1064:
1065:  Future<List<FileInfo>> _listDir(String dir) async => _fsOrThrow(
1066:    await _fs.listDir(dir),
1067:    'Failed to list session directory $dir',
1068:  );
