1070:  Future<SessionMetadata?> _tryLoadSessionMetadata(FileInfo entry) async {
1071:    try {
1072:      return await loadJsonlSessionMetadata(
1073:        _fs,
1074:        entry.path,
1075:        lastUpdatedAt: DateTime.fromMillisecondsSinceEpoch(entry.mtimeMs),
1076:        sizeBytes: entry.size,
1077:      );
1078:    } on SessionException catch (error) {
1079:      if (error.code != SessionErrorCode.invalidSession) rethrow;
1080:      return null;
1081:    }
1082:  }
