1084:  Future<List<SessionRecord>> _entriesToFork(
1085:    SessionStorage storage,
1086:    String? entryId,
1087:    ForkPosition position,
1088:  ) async {
1089:    if (entryId == null) return storage.getEntries();
1090:    final target = await storage.getEntry(entryId);
1091:    if (target == null) {
1092:      throw SessionException(
1093:        'Entry $entryId not found',
1094:        code: SessionErrorCode.invalidForkTarget,
1095:      );
1096:    }
1097:    String? effectiveLeafId;
1098:    if (position == ForkPosition.at) {
1099:      effectiveLeafId = target.id;
1100:    } else {
1101:      if (target is! MessageRecord || target.message.role != 'user') {
1102:        throw SessionException(
1103:          'Entry $entryId is not a user message',
1104:          code: SessionErrorCode.invalidForkTarget,
1105:        );
1106:      }
1107:      effectiveLeafId = target.parentId;
1108:    }
1109:    return storage.getPathToRoot(effectiveLeafId);
1110:  }
