1113:/// Blocked scanner behind [JsonlSessionRepo._readCustomRecordsStreamed];
1114:/// see its docstring. Stateful over the block stream: [scanBlock] feeds
1115:/// latin1-decoded blocks in file order, [finish] returns the decoded
1116:/// records (gating the crash-torn tail, if any).
1117:///
1118:/// Per-block pipeline: `latin1.decode` (byte→char identity memcpy —
1119:/// measured 3x cheaper than validating `utf8.decode`, 322ms vs 941ms
1120:/// on a 434MB marathon file), then gate-hit scanning via native
1121:/// `String.indexOf` — hits are as rare as the records themselves (14
1122:/// on that file), so full lines materialize only around an actual hit
1123:/// instead of substring-copying every line for a per-line `contains`.
1124:/// latin1 is byte-exact for the ASCII gate and line feeds, and
1125:/// `latin1.encode` restores a matching line's original bytes for the
1126:/// real `utf8.decode` + `jsonDecode` — semantics identical to the
1127:/// whole-file path.
1128:final class _CustomRecordBlockScanner {
1129:  _CustomRecordBlockScanner(Set<String> types)
1130:    : _types = types,
1131:      // Gate on the serialized field shape, not the bare type word: a
1132:      // loose substring gate passes every content line merely MENTIONING
1133:      // the type (1206 giant tool-result lines on a real marathon
1134:      // session, ~1.5s of pointless jsonDecode); the field-shaped gate
1135:      // passes the 14 real records. The writer is our own compact
1136:      // jsonEncode — the no-space shape is deterministic; the
1137:      // parsed-record check in _gateLine still decides correctness, the
1138:      // gate only prunes.
1139:      _gates = [for (final t in types) '"customType":"$t"'];
1140:
1141:  final Set<String> _types;
1142:  final List<String> _gates;
1143:  final _records = <CustomRecord>[];
1144:
1145:  /// Open line fragment carried across block boundaries (a line can
1146:  /// exceed one block, e.g. a 32KB message line).
1147:  final _carry = StringBuffer();
1148:
1149:  /// Pre-filter probe: the common prefix of all gates (for the boot-time
1150:  /// steering scan that is `"customType":"steering`) collapses the block
1151:  /// pre-filter to ONE contains pass — pure-Dart string search tops out
1152:  /// near 1.3GB/s on this VM, so two passes over a marathon file cost a
1153:  /// visible ~0.7s on their own. Too-short prefixes (degenerate type
1154:  /// sets) fall back to per-gate contains.
1155:  late final String _probe = _commonPrefix(_gates);
1156:
1157:  bool _blockMayMatch(String text) =>
1158:      _probe.length >= 6 ? text.contains(_probe) : _gates.any(text.contains);
1159:
1160:  void _gateLine(String line) {
1161:    if (_gates.any(line.contains)) {
1162:      JsonlSessionRepo._decodeCustomRecord(
1163:        json_conv.utf8.decode(json_conv.latin1.encode(line)),
1164:        _types,
1165:        _records,
1166:      );
1167:    }
1168:  }
1169:
1170:  /// Feeds one latin1-decoded block (file order).
1171:  void scanBlock(String text) {
1172:    // Complete the carried open line first, in EVERY path: a gate can
1173:    // span a block boundary (half in the carry, half in this block's
1174:    // head), so neither block's own scan sees it whole.
1175:    final firstNl = text.indexOf('\n');
1176:    if (firstNl < 0) {
1177:      _carry.write(text); // the whole block is inside one open line
1178:      return;
1179:    }
1180:    final hadCarry = _carry.isNotEmpty;
1181:    if (hadCarry) {
1182:      _gateLine(_carry.toString() + text.substring(0, firstNl));
1183:      _carry.clear();
1184:    }
1185:    // Block pre-filter: gate hits are as rare as the records themselves
1186:    // (14 on a real 434MB marathon file), and native `String.contains`
1187:    // over the block is ~12x faster than an `indexOf` hit-walk
1188:    // (measured), so most blocks cost two memchr passes and no line
1189:    // work at all.
1190:    if (_blockMayMatch(text)) {
1191:      // Hit-scan inside the matching block: only a real gate occurrence
1192:      // materializes its line. When nothing was carried, text[0..firstNl]
1193:      // is a COMPLETE line (the previous block ended exactly on '\n') and
1194:      // must be scanned too — starting at firstNl + 1 would silently skip
1195:      // a block-boundary-aligned record.
1196:      _scanGateHits(hadCarry ? firstNl + 1 : 0, text);
1197:    }
1198:    // Carry the trailing open fragment (after the last newline); a line
1199:    // may span into a later matching block.
1200:    final lastNl = text.lastIndexOf('\n');
1201:    if (lastNl + 1 < text.length) _carry.write(text.substring(lastNl + 1));
1202:  }
