      wakeExecutable: config.wakeExecutable,
      sessionId: sessionId,
      sessionName: sessionName,
    );
    final result = await _env.exec(
      command,
      options: ShellExecOptions(cwd: cwd),
    );
    return result.isOk
        ? null
        : 'shell exec failed: ${result.errorOrNull?.message ?? 'unknown error'}';
  }

