  /// [AgentPresence.busy] when a fresh busy marker exists, null otherwise
  /// (absent, malformed, or past [busyFreshWindow] — the activity
  /// heuristics decide).
  Future<AgentPresence?> _busyPresence(String mailboxDir) async {
    final text = (await _env.readTextFile(
      '$mailboxDir/.presence',
    )).valueOrNull?.trim();
    if (text == null) return null;
    final parts = text.split(' ');
    if (parts.length != 2 || parts.first != 'busy') return null;
    final markedAtMs = int.tryParse(parts[1]);
    if (markedAtMs == null) return null;
    final age = DateTime.now().difference(
      DateTime.fromMillisecondsSinceEpoch(markedAtMs),
    );
    return age.isNegative || age <= busyFreshWindow ? AgentPresence.busy : null;
  }

  /// The announced capabilities from the `.capabilities` marker; empty
  /// when absent or unreadable.
  Future<List<AgentCapability>> _capabilities(String mailboxDir) async {
    final text = (await _env.readTextFile(
      '$mailboxDir/.capabilities',
    )).valueOrNull;
    if (text == null || text.isEmpty) return const [];
    try {
      return AgentCapability.listFromJson(jsonDecode(text));
    } on FormatException {
      return const [];
    }
  }

  @override
  Future<void> send(AgentMessage message) async {
    // Cross-project routing: the recipient drains only ITS OWN cwd-slug
    // messages root, so a sender-rooted write into a foreign mailbox
    // silently vanishes (a peer fa in another project never sees it).
    // Resolve the mailbox's real root first: the messages-registry.json
    // slug map, then a broad scan of sibling slugs; unknown ids stay local.
    final root = await _resolveRecipientRoot(message.toId);
    final dir = '$root/${sanitizeAgentId(message.toId)}/inbox';
    (await _env.createDir(dir)).getOrThrow();
    final agentDir = '$root/${sanitizeAgentId(message.toId)}';
    // The real (unsanitized) id marker, so directory() can report
    // human-meaningful mailbox names instead of filesystem-safe ones.
    final marker = '$agentDir/.id';
    if ((await _env.exists(marker)).valueOrNull != true) {
      (await _env.writeFile(marker, message.toId)).getOrThrow();
    }
    final path = '$dir/${_fileName(message)}';
    (await _env.writeFile(path, jsonEncode(message.toJson()))).getOrThrow();
  }

  /// The messages root that actually backs [agentId]'s mailbox (issue #516):
  /// among every project root holding a mailbox with this id, a LIVE
  /// registration (fresh heartbeat) wins over any stale directory — an
