  final String _root;
  final String? _homeDir;
  final String? Function(String slug)? _decodeSessionCwd;

  static final _unsafeChars = RegExp(r'[^a-zA-Z0-9._-]');

  /// Filesystem-safe directory name for an agent id (`explore:a1` →
  /// `explore_a1`).
