      agentId.replaceAll(_unsafeChars, '_');

  String _inboxDir(String agentId) =>
      '$_root/${sanitizeAgentId(agentId)}/inbox';
  String _readDir(String agentId) => '$_root/${sanitizeAgentId(agentId)}/read';

  @override
