  final slash = to.indexOf('/');
  return (slash < 0
          ? entries.where((entry) => entry.name != null && entry.name == to)
          : entries.where(
              (entry) =>
                  entry.id.endsWith('/${to.substring(slash + 1)}') &&
                  entry.name == to.substring(0, slash),
