    String to = 'a1',
    String text = 'hello',
    String sentAt = '2026-01-01T00:00:00Z',
    int hops = 2,
  }) => AgentMessage(
    id: id,
    fromId: from,
    toId: to,
    text: text,
    sentAt: sentAt,
    hops: hops,
  );

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    repo = FileMessagingRepository(
      env: env,
      root: messagesRoot,
      homeDir: '/home/user',
