List<MailboxEntry> _nameMatches(List<MailboxEntry> entries, String to) {
  final slash = to.indexOf('/');
  return (slash < 0
          ? entries.where((entry) => entry.name != null && entry.name == to)
          : entries.where(
              (entry) =>
