    if (text == null) return null;
    final parts = text.split(' ');
    if (parts.length != 2 || parts.first != 'busy') return null;
    final markedAtMs = int.tryParse(parts[1]);
    if (markedAtMs == null) return null;
    final age = DateTime.now().difference(
