    id: id,
    fromId: from,
    toId: to,
    text: text,
    sentAt: sentAt,
    hops: hops,
  );

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    repo = FileMessagingRepository(
      env: env,
