      expect(
        decodeSessionCwd('--Users-Uladzimir_Klyshevich-git-dm.ai--'),
        '/Users/Uladzimir_Klyshevich/git/dm.ai',
      );
    });

    test('round-trips typical absolute paths', () {
      expect(decodeSessionCwd(encodeSessionCwd('/foo/bar')), '/foo/bar');
