  final bare = normalized.replaceFirst(RegExp(r'^[/\\]'), '');
  // Reversible escaping (gh-1744): separators stay `-`, but a literal `-`
  // must not be mistaken for one, so it (and every character the decoder
  // treats specially) rides percent-escapes. Paths without any of them
  // encode byte-identically to the legacy scheme, keeping existing
  // on-disk slug folders and pi's layout stable.
  final escaped = bare
      .replaceAll('%', '%25')
      .replaceAll('-', '%2D')
      .replaceAll('/', '%2F')
      .replaceAll(r'\', '%5C')
      .replaceAll(':', '%3A');
  return '--$escaped--';
}

