/// was written by the reversible encoder and must not go through the
/// legacy lossy split.
bool _hasReversibleEscape(String inner) => _slugEscape
    .allMatches(inner)
    .any((m) => const {'25', '2D', '2F', '5C', '3A'}
        .contains(m.group(1)!.toUpperCase()));

